<include file="Public:header"/><script type="text/javascript" src="{pigcms{$static_path}js/area_pca.js"></script>		<div class="mainbox">			<div id="nav" class="mainnav_title">				<ul>					<a href="{pigcms{:U('Platform/manage')}">平台分类列表</a>|					<a href="javascript:void(0);" onclick="window.top.artiframe('{pigcms{:U('Platform/add')}','添加分类',800,560,true,false,false,addbtn,'add',true);">添加分类</a>					<a href="{pigcms{:U('Platform/activity_list')}">平台活动列表</a>|                    <a href=""  class="on">平台活动评论列表</a>|					<a href="{pigcms{:U('Platform/checkList')}">分类管理员审核列表</a>|				</ul>			</div>			<table class="search_table" width="100%">				<tr>					<td style="width:60%;">						<form action="{pigcms{:U('Platform/activity_reply')}" method="get">							<input type="hidden" name="c" value="Platform"/>							<input type="hidden" name="a" value="activity_reply"/>							<!-- 活动主题: 							<input type="text" name="title" value="{pigcms{$_GET.title}" style="height: 22px;width: 70px;"/> -->							<!-- 订单号:							<input type="text" name="order_id" value="{pigcms{$_GET.order_id}" style="height: 22px;width: 70px;"/>							手机号:							<input type="text" name="phone" value="{pigcms{$_GET.phone}" style="height: 22px;width: 70px;"/> -->							用户昵称:							<input type="text" name="name" value="{pigcms{$_GET.name}" style="height: 22px;width: 70px;"/>							<input type="hidden" name="activity_id" value="{pigcms{$_GET.activity_id}" style="height: 22px;width: 70px;"/>							<input type="submit" value="查询" class="button"/>						</form>					</td>				</tr>			</table>							<div class="table-list">					<table width="100%" cellspacing="0">						<colgroup><col> <col> <col> <col><col><col><col><col><col width="240" align="center"> </colgroup>						<thead>							<tr>								<th>编号</th>								<th >活动主题</th>								<th>用户昵称</th>								<th>评价内容</th>								<th>评价星级</th>								<th>图片</th>								<th>是否匿名</th>								<!-- <th>报名自定义信息</th> -->								<th>添加时间</th>                                <th>评价讨论详情</th>								<th>操作</th>							</tr>						</thead>						<tbody>							<if condition="is_array($list)">								<volist name="list" id="vo">									<tr>										<td>{pigcms{$vo.id}</td>										<td>{pigcms{$vo.title}</td>										<td>{pigcms{$vo.nickname}</td>										<td>{pigcms{$vo.content}</td>										<td>{pigcms{$vo.reply_star}</td>										<td>											<if condition="$vo['images'] neq ''">											<a href="javascript:void(0);" onclick="window.top.artiframe('{pigcms{:U('Platform/reply_img',array('id'=>$vo['id']))}','查看图片信息',680,560,true,false,false,'','edit',true);">查看</a>											<else/>											</if>										</td>										<td>											<if condition="$vo['is_anonymous'] eq 1">												<font style="color:red;">是</font>											<else/>												<font style="color:green;">否</font>												</if>											</td>										<td><if condition="$vo['add_time']">{pigcms{$vo.add_time|date='Y-m-d H:i:s',###}<else/>无</if></td>                                        </td>                                        <td>                                            <a href="{pigcms{:U('Platform/activity_comment_reply',array('activity_id'=>$vo['activity_id'], 'fid' => $vo['id']))}">查看</a>                                        </td>                                        <td>										<a href="javascript:void(0);" class="delete_row" parameter="id={pigcms{$vo.id}" url="{pigcms{:U('Platform/del_reply')}">删除</a>										</td>									</tr>								</volist>								<tr><td class="textcenter pagebar" colspan="12">{pigcms{$pagebar}</td></tr>							<else/>								<tr><td class="textcenter red" colspan="10">列表为空！</td></tr>							</if>						</tbody>					</table>				</div>				</div><script>   var url = "{pigcms{$config.site_url}"    var export_url = "{pigcms{:U('Platform/export_info')}"</script><script type="text/javascript" src="{pigcms{$static_public}js/export.js"> </script><!-- <script>            var lockInfo = false;            function discoverSwitch(id, status) {            	console.log(id);                if (lockInfo) return;                lockInfo = true;                var url = '';                var close_category = "{pigcms{:U('Platform/close_cate')}";                var open_category = "{pigcms{:U('Platform/open_cate')}";                if (0 == status) {                    url = open_category;                } else if(1 == status) {                    url = close_category;                } else {                    return;                }                $.post(url,{'id': id},function(data){                    console.log(data)                    if (data && (data.status === 1 || data.status === '1')) {                        location.reload();                    } else {                        alert(data.info)                    }                },'json')                setTimeout(function(){                    lockInfo = false;                },1000);            }        </script> --><include file="Public:footer"/>